const tg = window.Telegram?.WebApp;

if (tg) {
  tg.ready();
  tg.expand();
}

axios.interceptors.request.use((config) => {
  const initData = window.Telegram?.WebApp?.initData || '';

  if (initData) {
    config.headers.set('X-Telegram-Init-Data', initData);
  }

  return config;
});

